function cleanSimpleFunction(x: number): number {
    if (x > 0) {
        return 1;
    }
    return 0;
}

function flaggedComplexFunction(status: string): number {
    if (status === "a") {
        return 1;
    } else if (status === "b") {
        return 2;
    } else if (status === "c") {
        return 3;
    } else if (status === "d") {
        return 4;
    } else if (status === "e") {
        return 5;
    } else if (status === "f") {
        return 6;
    } else if (status === "g") {
        return 7;
    } else if (status === "h") {
        return 8;
    } else if (status === "i") {
        return 9;
    } else if (status === "j") {
        return 10;
    } else if (status === "k") {
        return 11;
    }
    return 0;
}

